import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"This&That: Language-Gesture Controlled Video Generation for Robot Planning","description":"","frontmatter":{"title":"This&That: Language-Gesture Controlled Video Generation for Robot Planning","arxiv":"2407.05530","date":"2024-07-08","authors":"Boyang Wang, Nikhil Sridhar, Chao Feng, Mark Van der Merwe, Adam Fishman, Nima Fazeli, Jeong Joon Park","categories":"cs.RO, cs.AI, cs.CV","topics":"视频生成赋能具身智能, 手势条件视频生成, 视频条件行为克隆","outline":[2,2]},"headers":[],"relativePath":"papers/2407.05530.md","filePath":"papers/2407.05530.md","lastUpdated":null}'),l={name:"papers/2407.05530.md"};function e(i,s,r,m,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="this-that-language-gesture-controlled-video-generation-for-robot-planning" tabindex="-1">This&amp;That: Language-Gesture Controlled Video Generation for Robot Planning <a class="header-anchor" href="#this-that-language-gesture-controlled-video-generation-for-robot-planning" aria-label="Permalink to &quot;This&amp;That: Language-Gesture Controlled Video Generation for Robot Planning&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2407.05530" target="_blank" rel="noreferrer">2407.05530</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-07-08（v2 2025-05-18）</td></tr><tr><td><strong>作者</strong></td><td>Boyang Wang, Nikhil Sridhar, Chao Feng, Mark Van der Merwe, Adam Fishman, Nima Fazeli, Jeong Joon Park</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>在首帧上点两个 2D 点 + 一句「把这个放那儿」的指示代词，条件化视频扩散模型生成动作计划，再用一个交叉注意力读取整段预测视频的行为克隆网络把计划变成动作。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv abs 页当前指向 <strong>v2</strong>（2025-05-18），本文按 v2 全文撰写；v1 提交于 2024-07-08。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>用视频生成模型做机器人规划的思路已经成立：互联网视频里含有丰富的物理与语义先验，让模型「想象」任务完成的过程，再把想象变成动作。问题出在两端。输入端，现有工作几乎只用语言做条件，而语言在杂乱场景里是有歧义的——「把蓝色杯子递给我」在有三个蓝杯子时无法确定目标，把描述写得足够精确又会变得冗长。输出端，生成的视频要变成动作，现有做法要么把动作空间简化，要么单独训一个逆动力学模型，两者都与主流的行为克隆流程割裂。</p><p>This&amp;That 针对这两端各提一个方案：用「语言 + 手势」联合条件替代纯语言条件，用一个能对整段预测视频做交叉注意力的行为克隆架构替代逆动力学模型。前者的价值在于把人类日常最自然的指令形式（指着说「这个」「那儿」）搬进机器人接口；后者的价值在于让视频规划不再是一个孤立模块，而能与已经很成熟的 BC 流水线共用一套训练与部署方式。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>视频规划一侧，UniPi 与 UniSim 证明了文本到视频的生成可以模拟真实场景中的机器人交互，但都要靠逆动力学模型把视频翻译成动作；AVDC 自研了一套低分辨率 VDM，从生成视频里抽光流再离散化成动作；SuSIE 用自回归图像编辑模型预测下一个视觉子目标，低层策略只看单张目标图。这些方法的共同短板是条件端仍然是语言（或单张目标图），在目标本身有歧义的场景里，生成结果与用户意图无从对齐——不是模型画得不好，而是条件根本没有把意图说清楚。</p><p>视频可控生成一侧，MotionCtrl 把物体轨迹与相机位姿分别注入卷积层与时序层；DragAnything 和 Follow-Your-Click 用分割掩码定位目标物体并给每一帧提供完整轨迹；SparseCtrl 用通道拼接缓解稀疏时序条件的问题。它们要么需要稠密的空间信息（掩码），要么需要稠密的时序信息（逐帧轨迹）。而人类真实的指点行为只提供一两个像素点，落在这些方法的假设之外。作者的观察是：把 ControlNet 直接套过来并不奏效，因为条件在空间和时间上都极稀疏（首两帧各一个像素，其余帧全空），控制分支收到的输入几乎没有信号。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从 2024 年初的已知事实出发：大规模 I2V 模型（SVD）在机器人场景微调后已经能产出视觉质量可用的短视频；语言编码器（CLIP、BERT）在空间关系推理上被 NLP 社区反复证明是弱项；机器人数据集（Bridge）里既有第三人称视频也有语言标注，但没有任何手势标注。</p><p>一个认真的研究者会这样推：既然失败模式是「语言说不清哪一个」，那么补充的信息应当是空间定位而不是更长的语言。最省人力的空间信号是 2D 点击——它可以由用户点，也可以在训练时用夹爪检测与跟踪自动标注出来。接着的工程问题是：一两个像素的条件怎么才能被 UNet「听见」？ControlNet 的标准做法把条件图直接送进控制分支，但当条件图 99.99% 是零时，前几层卷积会把它当噪声抹掉。借鉴 SparseCtrl 的通道拼接思路，把首帧潜变量、当前去噪的视频潜变量和稀疏手势图沿通道拼在一起，控制分支每一步都能拿到稠密的视频内容，手势点便成为「在稠密上下文里的一个显著扰动」而不是「孤立的噪声」。最后一步：既然视频是密集的目标序列，就没必要退回单张目标图的 BC 范式，直接让 Transformer 编码器在观测与整段视频计划之间做交叉注意力。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>语言的信息瓶颈不在表达能力，而在指代（reference）：要唯一确定一个物体，语言必须把它与所有同类区分开，代价随场景复杂度增长；而一个 2D 点的指代成本是常数。把指代交给手势、把语义交给语言之后，「这个」「那儿」这种最短的指令就够用了。工程上真正让方法奏效的一点是：极稀疏的条件必须被嵌入到稠密的上下文里才能被扩散模型读取——单独送两个像素等于什么都没送。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 Bridge 场景「把布盖到这个物体上」为例，完整链路是：</p><ol><li><strong>输入</strong>：首帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（第三人称 RGB）、语言 <code>put this on that</code>、两个 2D 坐标（一个落在待抓物体上，一个落在目标位置上）。开门/关门这类只需接触点的任务只给一个点。</li><li><strong>语言条件微调</strong>：以 Stable Video Diffusion 为底座，用 CLIP 编码语言与首帧，通过语言-图像 token 交叉注意力得到调制参数，以 FiLM 方式调制 UNet 中间特征。训练时对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 加高斯噪声做噪声重建；因为机器人视频有明确的起止，直接对整段做均匀下采样取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 帧。</li><li><strong>手势条件分支</strong>：冻结主 UNet，训练一个与之并行的 ControlNet 式分支。分支的第一层卷积前，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0894em;">E</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>、当前噪声潜变量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与手势图潜变量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord mathcal" style="margin-right:0.0894em;">E</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord text mtight"><span class="mord mtight">gest</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 沿通道拼接；手势点先用 2D 高斯滤波做膨胀。分支同样被语言调制，输出加到主 UNet 的解码器上。</li><li><strong>手势标注</strong>：数据集没有真值手势，作者用夹爪与目标物体的 2D 检测与跟踪自动生成关键点，标注失败的视频被过滤掉（Bridge V1+V2 共 25,767 条用于第一阶段微调，14,735 条用于手势阶段）。</li><li><strong>DiVA 行为克隆</strong>：ResNet-18 编码视频计划各帧与当前观测，TokenLearner 把每帧压到 16 个 token；Transformer 编码器在观测 token 与计划 token 之间交叉注意力，解码器把固定位置嵌入解成动作块。训练时目标序列取自真值 demo 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 等分区间内的随机一帧（作为时间噪声增强），推理时换成 VDM 生成的帧。</li><li><strong>输出</strong>：末端执行器动作块 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>，在 IsaacGym 中执行。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>视频侧就是标准的条件潜空间扩散，唯一的形式化在于条件集合的构成：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">gest</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>这里 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">gest</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 是把 2D 坐标渲染成图像、再由 VAE 编码得到的稀疏图。理解要点是：扩散模型学的是「在给定条件下的视频分布」，当条件只有语言时，同一句话对应的合法视频集合在有歧义的场景里是多峰的；加入手势后这个集合被压缩到近似单峰。所以手势的作用不是提高画质，而是削减条件分布的熵——这也解释了为什么作者在 Fig. 6 里观察到语言-手势模型的视觉质量反而更高：训练时的不确定性更低。</p><p>动作侧是条件动作分布</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是实时观测、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是末端位姿、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 是视频计划的一个子集。与逆动力学模型 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 的关键差别在于条件是一整段未来而非相邻两帧，因此模型可以在时间上「对齐到自己认为合适的位置」，这也是作者引入时间噪声增强的原因：生成视频帧数固定而真实动作序列长度可变，若不做增强，轻微的时间错位就会造成误差。本文没有更深的理论推导。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：手势条件是否真的提升了与用户意图的对齐？</strong> 设计是人类主观评测：给定首帧、语言和手势，让被试判断生成视频是否符合意图（是/否），测试集 24 条 Bridge 序列分为抓放、堆叠、折叠、开关四类，每类同时用「常规文本」和「指示代词文本」两种语言。结论明确：视觉+语言+手势在常规文本下平均 91.7%、指示代词下 87.5%；只有视觉+语言时分别是 51.4% 和 25.0%；只有视觉+手势是 68.1%。换言之，加了手势之后，把语言退化成「this/that」几乎不掉分（91.7 → 87.5），而纯语言在退化后直接腰斩。开关类任务四种配置差别很小（语言基本无歧义），正好构成一个阴性对照。</p><p><strong>问题二：生成质量是否也更好？</strong> 在 646 条 Bridge 测试视频上比 SVD、StreamingT2V、DragAnything 与 AVDC。本文 FID 17.28 / FVD 84.58 / PSNR 21.71 / SSIM 0.787 / LPIPS 0.112，全部指标最优；AVDC 的 FVD 高达 1512.25，而作者特别注明 AVDC 在训练时见过这些测试视频。</p><p><strong>问题三：视频计划能否变成动作？</strong> 在 IsaacGym 里搭四方块桌面场景，用手写脚本策略采集真值轨迹，并构造「两个完全相同的方块」作为分布外压力测试（表中以 in-distribution / out-of-distribution 双数值给出）。完整流水线的抓取成功率 95/87、放置 93/80；ACT（视觉+语言+手势）只有 57/56 与 35/35；AVDC + DiVA 是 67/40 与 46/14；本文自己的语言条件版本是 93/60 与 82/26。两个读数值得注意：一是视频规划相对直接 BC 的增益很大，二是语言版本在分布内还行（93/82）、在分布外崩到 60/26，而手势版本几乎不掉——这正是歧义假设的直接验证。</p><p><strong>局限</strong>：作者自陈物体形状会随时间漂移（缺 3D 约束）；只做短程模块化任务；BC 实验全部在仿真中，因为实验室没有 WidowX 250 机械臂，无法在 Bridge 的真机上验证。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：语言在杂乱场景中的失效不是表达力问题而是指代成本问题，2D 指点的指代成本是常数。把手势作为 ControlNet 式旁路注入视频扩散模型时，必须把稀疏条件与首帧潜变量、当前噪声潜变量沿通道拼接，否则控制分支读不到信号。加入手势后，指令可以退化成「this/that」而对齐率几乎不降（91.7 → 87.5），纯语言则从 51.4 掉到 25.0。生成的视频计划不必再经过逆动力学模型，用 TokenLearner 压缩 + 交叉注意力即可并入常规行为克隆。仿真中语言-手势流水线在「两个一模一样的方块」这一分布外设定上保持 87/80，而纯语言版本掉到 60/26。</p><p><strong>3 句话版</strong>：手势提供常数成本的指代，语言提供语义，两者合起来让极短指令也能唯一确定任务。稀疏手势要靠通道拼接嵌入稠密上下文才能被扩散模型利用。视频计划可以直接以整段序列的形式喂给行为克隆策略，不需要单独的逆动力学模型。</p><p><strong>1 句话版</strong>：给视频生成规划器加两个像素的指点，比给它加一百个字的描述更有效。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>真值视频帧与模型生成帧之间没有实质域差</strong>。作者明确选择「不在 VDM 生成帧上训练 DiVA」，理由是想证明域差很小；训练时用真值 demo 的等分采样帧作目标，推理时直接换成生成帧。整条流水线的成功率完全押在这个替换上。</p><p>它在实践中很可能不成立：VDM 的输出在物体形状上会漂移（作者自己在 Limitations 里承认），而 DiVA 的输入是 ResNet-18 特征经 TokenLearner 压到 16 token——这类压缩对纹理不敏感但对物体位置敏感，恰恰是生成误差最大的维度。论文为此提供的证据是间接的：一是引入时间噪声增强来提升鲁棒性，二是最终仿真成功率很高。缺的是直接证据：没有一张「用真值视频作计划 vs 用生成视频作计划」的成功率对照表，因此无法判断 95/87 里有多少被生成质量吃掉。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，且不需要复现视频模型的训练：</p><ul><li>拿开源的 DiVA 结构（Transformer 编码器-解码器 + TokenLearner），在 IsaacGym 上用脚本策略采 2000 条抓放轨迹。</li><li>训练一个只用真值等分帧作目标的 DiVA。</li><li>评测三档计划：(a) 真值帧；(b) 真值帧加受控扰动（对目标物体外接框做 5/10/20 像素的随机平移，模拟生成漂移）；(c) 真值帧做形状扰动（轻度弹性形变，模拟形状不守恒）。</li><li>度量：抓取与放置成功率随扰动幅度的曲线。</li><li>判据：若成功率在 10 像素平移下下降不足 5 个百分点，说明「无域差」假设站得住，本文结论稳固；若在 5 像素就掉 20 个百分点以上，则 95/87 这类数字强烈依赖于该仿真场景中 VDM 的偶然精度，换个场景不可复制。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>替代解释：<strong>增益的主要来源是「策略拿到了目标物体的 2D 坐标」，而不是「视频生成器把意图渲染成了计划」</strong>。支持这一读法的证据就在论文自己的表里：ACT 从视觉+语言的 3/3、0/0 加上手势后跳到 57/56、35/35——一个完全不含视频生成的策略，仅靠两个坐标就拿到了大部分绝对增益。剩下的差距（57 → 95）当然显著，但它同时混杂了「有密集视觉目标序列」与「模型容量/训练方式不同」两件事。</p><p>设计一个能分离二者的实验：保持 DiVA 结构与训练完全不变，把视频计划 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 换成三种等 token 预算的替代品——(a) 首帧重复 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 次，并在两个手势点位置画上高斯标记；(b) 首帧重复 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 次 + 手势标记按直线插值移动（一条「假计划」，完全不含物理）；(c) 真实生成视频。如果 (b) 与 (c) 的成功率接近，那么「视频生成器提供了物理与语义先验」这一叙事就被削弱到只剩「它提供了一条从起点到终点的空间轨迹」，而后者用几何插值就能免费得到。同一场景还给出可预测的失效条件：当任务的关键信息不是「哪一个物体、移到哪里」而是「怎么动」（如折叠、倒液体的过程约束）时，坐标解释会失效而视频解释应当胜出——论文的折叠类任务在人评上是 88.9/94.4，值得单独做这项对照。</p><p>另有一处评测设计上的不对称需要注意：分布外场景被定义为「两个形状颜色完全相同的方块」，这恰好是 2D 点唯一能而语言不能解决的情形；作者虽然给语言基线补了 front/back/left/right 这类绝对方位词，但这仍是为手势量身定制的难度轴。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：本文把手势当成一个恒定提供的条件，用户每次都要点。可真实交互里，大多数指令并不需要手势——论文的开关类任务四种配置几乎同分就是证据。反过来，在真正有歧义时，一个点可能还不够（作者在 Fig. 6 指出 2D 点存在 3D 深度歧义）。固定条件格式既浪费了用户带宽，也在该问的时候不问。</p><p><strong>(b) 新的 framing 与可借的工具</strong>：把「人给机器人下指令」重构成<strong>最小充分指令协议</strong>——目标不是「让模型服从条件」，而是「用最少的人类比特把条件分布的熵压到阈值以下」。可借鉴的相邻领域有两个：最优实验设计/主动学习里的期望信息增益准则，用来决定「下一个最有价值的查询是点一个点、说一个词，还是给一个深度提示」；以及指代表达生成（referring expression generation）里的语用推理模型，用来在语言与手势之间做成本-收益权衡。扩散模型本身提供了熵的可计算代理：对同一条件采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 条视频，度量目标物体位置在样本间的分散度。</p><p><strong>(c) 第一个实验</strong>：在 Bridge 测试集上，对每条纯语言条件采 8 条视频，用现成的检测器算被操作物体末位置的方差；据此把样本分成「低熵」与「高熵」两档。假设：低熵档加手势不改善人评对齐率，高熵档加手势的改善远大于论文报告的平均值。若成立，就可以训练一个只有几百万参数的「提问器」，在高熵时才请求点击，并把节省下来的交互轮次量化成协议效率——这比继续给视频模型加控制模态更有意思，因为它把评价指标从「生成质量」换成了「达成共识所需的人类努力」。</p>',48)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
